import json, sys, html as _h

BOOK = {'title': 'Starfall Protocol', 'author': 'Signature original', 'genre': 'Galactic Empires', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "Commander Sera Ilsa gave the order anyway. The engines lit, the deck hummed, and the ship leapt toward a coded starlog with New Ceres Colony falling behind. Some cargoes, Commander Sera Ilsa knew, are worth the whole sky.\n\nThe klaxon woke Commander Sera Ilsa before the dawn cycle. On the viewscreen, New Ceres Colony glittered — and tumbling toward it, broadcasting on all bands, was a coded starlog. 'Signal Officer Luz Marek,' Commander Sera Ilsa said, 'plot an intercept. Quietly.'\n\nSignal Officer Luz Marek ran the numbers with grease on their hands and worry in their eyes. 'Warlord Krell has three ships in the drift,' they said. 'If we burn hard, we can make it. If we burn hard, everyone will see us.'"}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "In the quiet after, Commander Sera Ilsa played the starlog again. The voice — old, tired, kind — said: 'Whoever finds this, New Ceres Colony needs you. Hurry.' Commander Sera Ilsa set the course and did not look back.\n\nThey burned for the first waypoint with raiders on their tail. Commander Sera Ilsa flew the ship like a thrown knife, skimming a gravity well so close the hull sang. Behind them, Warlord Krell's vanguard broke off, unwilling to follow.\n\n'It's a map,' breathed Commander Sera Ilsa, 'and a warning.' The route it drew cut through the worst of the drift: plasma storms, minefields, and the patrol lanes of Warlord Krell."}, {'n': 3, 'title': 'Storm Season', 'text': "Through the fire they saw it: Warlord Krell's flagship, waiting in the storm's eye like a spider. 'They knew the route,' Commander Sera Ilsa said. 'Someone sold the starlog.' The betrayal sat cold in their stomach.\n\nThe battle was short and ugly. Commander Sera Ilsa used the storm itself as a weapon, luring the flagship into a plasma surge that stripped its shields. They escaped in the glare, hull scorched, crew cheering raggedly.\n\nAfterward, Commander Sera Ilsa looked at each face on the bridge and said it plainly: 'There's a traitor aboard. I don't know who. But a coded starlog goes to New Ceres Colony — with all of us, or with whoever's left.'"}, {'n': 4, 'title': "The Traitor's Price", 'text': "Commander Sera Ilsa let them live, confined to quarters. 'Warlord Krell trades in hostages,' Commander Sera Ilsa told the crew. 'We trade in something better.' It was a gamble; the crew's eyes said they knew it.\n\nCommander Sera Ilsa laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' Signal Officer Luz Marek was already calculating the wake-up sequence.\n\nSignal Officer Luz Marek caught them at the airlock. There was no fight — only the traitor crying that Warlord Krell held their family. Commander Sera Ilsa understood, and hated understanding. Mercy, out here, was a luxury with teeth."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "The flagship came on anyway, and Commander Sera Ilsa met it ship to ship above the burning sky. It was Warlord Krell themselves on the viewscreen, offering one last deal. Commander Sera Ilsa answered with the engines at full burn.\n\nSilence, then. The grid humming. New Ceres Colony safe below. Signal Officer Luz Marek put a hand on Commander Sera Ilsa's shoulder and said what everyone was thinking: 'We live.'\n\nThey reached New Ceres Colony with Warlord Krell's whole fleet behind them, a wall of iron against the stars. Commander Sera Ilsa broadcast on all bands: 'People of New Ceres Colony, wake the grid. Now.'"}, {'n': 6, 'title': 'Home Signal', 'text': "Commander Sera Ilsa stood on the hull at sunset, watching New Ceres Colony turn below. light against the void — the stars had taught it, and the crew had proved it, and the grid would remember it.\n\nSignal Officer Luz Marek was offered an admiralty and laughed in the committee's face. 'I have a ship,' they said. It was the highest compliment the crew had ever heard.\n\nAnd when the next distress call came — as it always does, out in the drift — the engines were already warm. There are always more skies. There is always New Ceres Colony, somewhere, needing its heroes."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

